const $=id=>document.getElementById(id),datasets=[null,null];let compared=[];
function message(s){$('message').textContent=s;}
function mappingUI(i){const parsed=datasets[i];const wrapper=document.createElement('section');wrapper.className='settings';const title=document.createElement('h3');title.textContent='Shop '+(i?'B':'A')+' column mapping';wrapper.append(title);const found=CatalogCore.mapping(parsed.headers);for(const field of ['name','price','sku','brand','url','stock']){const group=document.createElement('div');group.className='setting';const label=document.createElement('label');label.textContent=field+(field==='name'||field==='price'?' *':'');const select=document.createElement('select');select.dataset.file=i;select.dataset.field=field;select.append(new Option('Not present',''));for(const h of parsed.headers)select.append(new Option(h,h));select.value=found[field];group.append(label,select);wrapper.append(group);}return wrapper;}
async function load(i,file){if(!file)return;if(file.size>10*1024*1024){message('File must be under 10 MB.');return;}try{const content=new TextDecoder('utf-8',{fatal:true}).decode(await file.arrayBuffer());datasets[i]=CSVCore.parse(content);$('info-'+(i?'b':'a')).textContent=file.name+' · '+datasets[i].rows.length+' rows';$('mappings').replaceChildren(...datasets.map((d,j)=>d?mappingUI(j):document.createTextNode('')));$('compare').disabled=!datasets.every(Boolean);$('results').hidden=true;message('');}catch(e){datasets[i]=null;$('compare').disabled=true;message(e.message);}}
$('file-a').addEventListener('change',e=>load(0,e.target.files[0]));$('file-b').addEventListener('change',e=>load(1,e.target.files[0]));
$('compare').addEventListener('click',()=>{try{const getMap=i=>{const out={};for(const el of $('mappings').querySelectorAll('select'))if(Number(el.dataset.file)===i)out[el.dataset.field]=el.value;return out;};const a=CatalogCore.items(datasets[0],getMap(0),$('shop-a').value),b=CatalogCore.items(datasets[1],getMap(1),$('shop-b').value);compared=CatalogCore.compare(a,b);$('results').hidden=false;message('');render();}catch(e){message(e.message);}});
function render(){const q=$('search').value.toLowerCase(),status=$('filter').value;const rows=compared.filter(r=>(status==='all'||r.status===status)&&(!q||((r.a?.name||'')+' '+(r.b?.name||'')+' '+(r.a?.sku||'')+' '+(r.b?.sku||'')).toLowerCase().includes(q)));const sort=$('sort').value;rows.sort((a,b)=>sort==='name'?(a.a?.name||a.b?.name||'').localeCompare(b.a?.name||b.b?.name||''):sort==='price-a'?(a.a?.price??Infinity)-(b.a?.price??Infinity):sort==='price-b'?(a.b?.price??Infinity)-(b.b?.price??Infinity):Math.abs(b.difference??0)-Math.abs(a.difference??0));$('summary').textContent=rows.length+' displayed / '+compared.length+' total';$('body').replaceChildren();for(const r of rows.slice(0,1000)){const tr=document.createElement('tr');const values=[r.status+(r.reason?' — '+r.reason:''),r.a?.name||r.b?.name||'',r.a?.rawPrice||'—',r.b?.rawPrice||'—',Number.isFinite(r.difference)?r.difference.toFixed(2):'—'];for(const value of values){const td=document.createElement('td');td.textContent=value;tr.append(td);}$('body').append(tr);}if(rows.length>1000)message('Showing first 1,000 filtered results. CSV export includes all rows.');else message('');}
for(const id of ['filter','sort','search'])$(id).addEventListener(id==='search'?'input':'change',render);
$('export').addEventListener('click',()=>{const lines=[['Status','Shop A','Shop B','Name A','Name B','SKU A','SKU B','Price A','Price B','Difference B-A','URL A','URL B','Note'],...compared.map(r=>[r.status,r.a?.shop,r.b?.shop,r.a?.name,r.b?.name,r.a?.sku,r.b?.sku,r.a?.rawPrice,r.b?.rawPrice,r.difference??'',r.a?.url,r.b?.url,r.reason||''])];const blob=new Blob([CSVCore.csv(lines)],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='catalogue-comparison.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
